PCSScientificAuthorityV2.CompleteAuditFacts.finalIncumbent {root : PCSAuthorizationHistoryV1.Root}
  {verify : PCSAuthorizationHistoryV1.VerifySignature} {es : List PCSAuthorizationHistoryV1.Envelope}
