PCSScientificAuthorityV2.CompleteAuditFacts.generation {root : PCSAuthorizationHistoryV1.Root}
  {verify : PCSAuthorizationHistoryV1.VerifySignature} {es : List PCSAuthorizationHistoryV1.Envelope}
  {final : PCSAuthorizationHistoryV1.State} (self : PCSScientificAuthorityV2.CompleteAuditFacts root verify es final) :
  final.generation = root.genesisGeneration + es.length

PCSScientificAuthorityV2.CompleteAuditFacts.genesis {root : PCSAuthorizationHistoryV1.Root}
  {verify : PCSAuthorizationHistoryV1.VerifySignature} {es : List PCSAuthorizationHistoryV1.Envelope}
  {final : PCSAuthorizationHistoryV1.State} (self : PCSScientificAuthorityV2.CompleteAuditFacts root verify es final) :
