PCSScientificAuthorityV2.RecoveryFacts.checkpoint {root : PCSAuthorizationHistoryV1.Root}
  {verify : PCSAuthorizationHistoryV1.VerifySignature} {w : PCSScientificAuthorityV2.Witness}
  {archive : List PCSAuthorizationHistoryV1.Envelope} {a : PCSScientificAuthorityV2.Authority}
  (self : PCSScientificAuthorityV2.RecoveryFacts root verify w archive a) : a.localState = w.committed

